/*
	Tapete #WCCChallenge "Maze" //20260709
	https://openprocessing.org/@epi/2978180
	#generativeart #creativecoding #p5js

	Dear Raph and creative coding community,

	revised an older sketch displaying a subdivided grid,
   each of 5x5 cells in a homogene or heterogene palette color
   distribution.

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let epiColors; // https://github.com/epibyte/p5-epi-colors
let S, OX, OY, seed, shuffle_palettes;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of randomly subdived 5x5 cells");
	frameRate(15);
	// pixelDensity(1);
	noStroke();

	init();
}
function init() {
	let w = windowWidth, h = windowHeight;
	S = min(w, h);
	let num = 0;
	let _wG_1 = 0; while ((S > 6) && ++_wG_1 < 20000) {
		S /= 6;
		num++;
	}
	// ensure dividable tiles without subpixels
	for (let i = 0; i < num; i++) {
		S = ~~S * 6;
	}
	// console.log(w, h, S, num, S/num);
	S /= num;
	w = S * ~~(w/S);
	h = S * ~~(h/S);
	OX = w-width - S/2;
	OY = h-height - S/2;
	// console.log(w, h, S, OX, OY);

	// seed
	seed = random(123454321);
	noiseSeed(seed);
	randomSeed(seed);

	// colors
	const { EpiColors } = EpiColorsPckg;
	epiColors = new EpiColors();

	epiColors.getRandomPalette();
	shuffle_palettes = random() < 0.5;

	draw();

	// noLoop();
}

function draw() {
	background(32);

	noiseSeed(seed);
	randomSeed(seed);

	for (let y = OY; y < height; y += (Math.max(0.001, Math.abs(S)) || 1)) {		
		for (let x = OX; x < width; x += (Math.max(0.001, Math.abs(S)) || 1)) {
			drawTile(x, y, S)
		}
	}
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	init();
}

function mousePressed() {
	if (mouseButton !== RIGHT && mouseX > 0.1*width) {
		init();
	}
}

function drawTile(x, y, S) {
	if (S > 25 && random()<0.5) {
		// subdivide
		S /= 2;
		drawTile(x, y, S);
		drawTile(x+S, y, S);
		drawTile(x, y+S, S);
		drawTile(x+S, y+S, S);

	} else {
		// only darw visible tiles
		if ((x > width && y > height) || x+S < 0 || y+S < 0) return;

		// draw pattern
		// fill(random(200, 300), random(200), random(100, 200));
		if (shuffle_palettes) epiColors.getRandomPalette();
		const CLRS = [...epiColors.palette];
		shuffle(CLRS, true);
		fill(CLRS.pop()); // epiColors.getRandomClr()
		rect(x, y, S);

		const num = 5;
		S/=(num+1); x+=S/2; y+= S/2;

		let arr = Array(num*num);
		for (let k = 0; k < arr.length; k++) {
			const rndVal = random(); // noise(x, y, frameCount/321); // random()
			arr[k] = rndVal < (k%2 ? 0.6 : 0.8); // keep foundation with higher probability
		}
		arr[6] = false; arr[8] = false; arr[16] = false; arr[18] = false; // delete cells direct diagional to the center

		for (let j = 0, k = 0; j < num; j++) {			
			for (let i = 0; i < num; i++, k++) {
				if (arr[k]) {
					// fill(255, random(150, 200));
					// const clr = CLRS[~~random(CLRS.length/2)];
					const clr = CLRS[~~(noise(x+i, y+j, frameCount/321)*CLRS.length/2)];
					fill(clr); // limit clrs per tile, instead of: fill(random(CLRS));
					rect(x+j*S, y+i*S, S);
				}
			}
		}
	}
}

// --- Immunity Guardrails & Fallbacks ---
if (typeof EpiColorsPckg === 'undefined') {
  window.EpiColorsPckg = {
    EpiColors: function() {
      this.palette = ['#e74645', '#fb7756', '#facd60', '#fdfa66', '#1ac0c6', '#454d66', '#309975', '#58b368'];
      this.getRandomPalette = function() {
        this.palette = ['#e74645', '#fb7756', '#facd60', '#fdfa66', '#1ac0c6', '#454d66', '#309975', '#58b368'].sort(() => Math.random() - 0.5);
      };
      this.getRandomClr = function() {
        return this.palette[Math.floor(Math.random() * this.palette.length)];
      };
    }
  };
}
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

